import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import {
    Box,
    TextField,
    Button,
    Typography,
    Alert,
    CircularProgress,
    InputAdornment,
    IconButton
} from '@mui/material';
import EmailIcon from '@mui/icons-material/Email';
import VisibilityIcon from '@mui/icons-material/Visibility';
import VisibilityOffIcon from '@mui/icons-material/VisibilityOff';
import { utilisateurService } from '../services/utilisateurService';

// Styles constants
const styles = {
    container: {
        minHeight: '100vh',
        background: 'linear-gradient(180deg, #ffffff 1%, #cfcfcf 43%, #999999 100%)',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        position: 'relative' as const
    },
    logo: {
        position: 'absolute' as const,
        left: '28px',
        top: '0',
        zIndex: 10
    },
    illustration: {
        position: 'absolute' as const,
        left: '135px',
        top: '192px',
        width: '400px',
        height: '400px'
    },
    formContainer: {
        position: 'absolute' as const,
        left: '715px',
        top: '203px',
        width: '379px'
    },
    title: {
        fontFamily: 'Poppins, sans-serif',
        fontWeight: 800,
        fontSize: '32px',
        background: 'linear-gradient(34deg, #000204 0%, #773399 100%)',
        WebkitBackgroundClip: 'text' as const,
        WebkitTextFillColor: 'transparent' as const,
        backgroundClip: 'text' as const,
        textAlign: 'center' as const,
        mb: '30px'
    },
    label: {
        display: 'block',
        fontFamily: 'Poppins, sans-serif',
        fontWeight: 200,
        fontSize: '14px',
        color: '#333',
        mb: '8px'
    },
    textField: {
        '& .MuiInputBase-root': {
            height: '37px',
            backgroundColor: '#a9a9a9',
            borderRadius: '15px',
            '& fieldset': { border: 'none' }
        },
        '& .MuiInputBase-input': {
            padding: '0 45px 0 15px',
            fontFamily: 'Poppins, sans-serif',
            fontSize: '14px',
            color: '#333'
        }
    },
    button: {
        width: '238px',
        height: '50px',
        background: 'linear-gradient(0deg, #01111d 0%, #773399 100%)',
        borderRadius: '45px',
        fontFamily: 'Poppins, sans-serif',
        fontWeight: 800,
        fontSize: '20px',
        color: 'white',
        margin: '15px auto 25px auto',
        display: 'block',
        transition: 'all 0.3s ease',
        boxShadow: '0 5px 15px rgba(119, 51, 153, 0.3)',
        '&:hover': {
            opacity: 0.9,
            transform: 'translateY(-2px)',
            boxShadow: '0 8px 20px rgba(119, 51, 153, 0.4)'
        },
        '&:active': { transform: 'scale(0.98)' }
    },
    link: {
        fontFamily: 'Poppins, sans-serif',
        fontSize: '14px',
        color: '#333',
        textDecoration: 'none',
        transition: 'color 0.3s ease',
        flex: 1,
        '&:hover': {
            color: '#773399',
            textDecoration: 'underline'
        }
    }
};

const Login: React.FC = () => {
    const navigate = useNavigate();
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [showPassword, setShowPassword] = useState(false);
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        
        if (!email || !password) {
            setError('Veuillez remplir tous les champs');
            return;
        }
        
        setLoading(true);
        setError(null);
        
        try {
            const response = await utilisateurService.connexion(email, password);
            localStorage.setItem('userId', response.data.utilisateurId.toString());
            navigate('/profil');
        } catch (err: any) {
            setError(err.response?.data?.error || 'Email ou mot de passe incorrect');
        } finally {
            setLoading(false);
        }
    };

    return (
        <Box sx={styles.container}>
            {/* Logo */}
            <Box sx={styles.logo}>
                <img src="/Icons/logo.png" alt="Booklovers logo" />
            </Box>

            {/* Illustration */}
            <Box sx={styles.illustration}>
                <img src="/Icons/auth.png" alt="Illustration" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
            </Box>

            {/* Formulaire */}
            <Box sx={styles.formContainer}>
                <Typography variant="h4" sx={styles.title}>Login</Typography>

                {error && <Alert severity="error" sx={{ mb: 2, borderRadius: '5px' }}>{error}</Alert>}

                <form onSubmit={handleSubmit}>
                    {/* Champ Email */}
                    <Box sx={{ mb: '25px' }}>
                        <Typography component="label" sx={styles.label}>Email</Typography>
                        <TextField
                            fullWidth
                            name="email"
                            type="email"
                            placeholder="Votre email"
                            value={email}
                            onChange={(e) => setEmail(e.target.value)}
                            required
                            sx={styles.textField}
                            slotProps={{
                                input: {
                                    endAdornment: (
                                        <InputAdornment position="end">
                                            <EmailIcon sx={{ color: '#666', width: '29px' }} />
                                        </InputAdornment>
                                    )
                                }
                            }}
                        />
                    </Box>

                    {/* Champ Mot de passe */}
                    <Box sx={{ mb: '25px' }}>
                        <Typography component="label" sx={styles.label}>Mot de passe</Typography>
                        <TextField
                            fullWidth
                            name="mot_de_passe"
                            type={showPassword ? 'text' : 'password'}
                            placeholder="Votre mot de passe"
                            value={password}
                            onChange={(e) => setPassword(e.target.value)}
                            required
                            sx={styles.textField}
                            slotProps={{
                                input: {
                                    endAdornment: (
                                        <InputAdornment position="end">
                                            <IconButton onClick={() => setShowPassword(!showPassword)} edge="end" sx={{ padding: 0 }}>
                                                {showPassword ? (
                                                    <VisibilityOffIcon sx={{ color: '#666', width: '31px' }} />
                                                ) : (
                                                    <VisibilityIcon sx={{ color: '#666', width: '31px' }} />
                                                )}
                                            </IconButton>
                                        </InputAdornment>
                                    )
                                }
                            }}
                        />
                    </Box>

                    {/* Bouton */}
                    <Button type="submit" disabled={loading} sx={styles.button}>
                        {loading ? <CircularProgress size={28} color="inherit" /> : 'Connecter'}
                    </Button>

                    {/* Liens */}
                    <Box sx={{ display: 'flex', justifyContent: 'space-between', width: '373px', gap: '20px' }}>
                        <Typography component="a" href="/inscription" sx={styles.link}>Créer un compte</Typography>
                        <Typography component="a" href="/mdpOublie" sx={styles.link}>Mot de passe oublié</Typography>
                    </Box>
                </form>
            </Box>
        </Box>
    );
};

export default Login;
